//! Error taxonomy for the job runner.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RetryError {
    /// Transient faults may be retried (network blips, temporary locks).
    Transient(String),
    /// Permanent faults must return immediately (bad input, missing job).
    Permanent(String),
}

impl RetryError {
    /// Returns `true` for transient faults that may be retried. Permanent
    /// faults return `false` and are never retried.
    pub fn is_transient(&self) -> bool {
        matches!(self, RetryError::Transient(_))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn transient_is_retryable() {
        assert!(RetryError::Transient("boom".into()).is_transient());
    }

    #[test]
    fn permanent_is_not_retryable() {
        assert!(!RetryError::Permanent("boom".into()).is_transient());
    }
}

//! Retry configuration.

/// Bounded exponential retry configuration.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RetryConfig {
    /// Total attempts allowed, including the first call. Must be >= 1.
    pub max_attempts: u32,
    /// Base delay before the first retry, in milliseconds.
    pub base_delay_ms: u64,
    /// Upper bound for any retry delay, in milliseconds. Delay growth
    /// saturates at this value and never exceeds it.
    pub max_delay_ms: u64,
}

impl RetryConfig {
    /// Returns the delay, in milliseconds, to wait before the retry that
    /// follows `failed_attempts` consecutive failures (0 = the first retry).
    ///
    /// The delay doubles for every additional failure and saturates at
    /// `max_delay_ms`. The computation uses saturating arithmetic, so even
    /// an extremely large exponent saturates without overflowing `u64`.
    pub fn retry_delay_ms(&self, failed_attempts: u32) -> u64 {
        let mut delay = self.base_delay_ms;
        for _ in 0..failed_attempts {
            delay = delay.saturating_mul(2).min(self.max_delay_ms);
            if delay == self.max_delay_ms {
                break;
            }
        }
        delay.min(self.max_delay_ms)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn config(max_attempts: u32, base_delay_ms: u64, max_delay_ms: u64) -> RetryConfig {
        RetryConfig {
            max_attempts,
            base_delay_ms,
            max_delay_ms,
        }
    }

    #[test]
    fn delays_double_and_saturate() {
        let cfg = config(10, 10, 1000);
        assert_eq!(cfg.retry_delay_ms(0), 10);
        assert_eq!(cfg.retry_delay_ms(1), 20);
        assert_eq!(cfg.retry_delay_ms(2), 40);
        assert_eq!(cfg.retry_delay_ms(3), 80);
        assert_eq!(cfg.retry_delay_ms(4), 160);
        assert_eq!(cfg.retry_delay_ms(5), 320);
        assert_eq!(cfg.retry_delay_ms(6), 640);
        assert_eq!(cfg.retry_delay_ms(7), 1000);
        assert_eq!(cfg.retry_delay_ms(100), 1000);
    }

    #[test]
    fn huge_exponent_saturates_without_overflow() {
        let cfg = config(10, 1, u64::MAX);
        assert_eq!(cfg.retry_delay_ms(63), 1u64 << 63);
        assert_eq!(cfg.retry_delay_ms(64), u64::MAX);
        assert_eq!(cfg.retry_delay_ms(1_000_000), u64::MAX);
    }

    #[test]
    fn base_delay_above_max_is_capped() {
        let cfg = config(10, 5000, 100);
        assert_eq!(cfg.retry_delay_ms(0), 100);
        assert_eq!(cfg.retry_delay_ms(42), 100);
    }

    #[test]
    fn zero_delays_stay_zero() {
        let cfg = config(10, 0, 0);
        assert_eq!(cfg.retry_delay_ms(0), 0);
        assert_eq!(cfg.retry_delay_ms(100), 0);
    }
}

//! Injected sleeper so tests never really wait.
pub trait Sleeper {
    fn sleep_ms(&mut self, ms: u64);
}

/// Records every requested delay instead of waiting.
#[derive(Debug, Default)]
pub struct FakeSleeper {
    pub sleeps: Vec<u64>,
}

impl Sleeper for FakeSleeper {
    fn sleep_ms(&mut self, ms: u64) {
        self.sleeps.push(ms);
    }
}

mod config;
mod error;
mod sleeper;

pub use config::RetryConfig;
pub use error::RetryError;
pub use sleeper::{FakeSleeper, Sleeper};

/// Runs `job` until it succeeds or the retry budget is exhausted.
/// The public signature is frozen; do not change it.
///
/// Transient errors are retried with an exponential backoff that doubles
/// from `base_delay_ms` and saturates at `max_delay_ms`; permanent errors
/// abort immediately. `max_attempts` includes the first call.
pub fn run_job(
    config: &RetryConfig,
    sleeper: &mut dyn Sleeper,
    mut job: impl FnMut() -> Result<(), RetryError>,
) -> Result<(), RetryError> {
    let mut failed_attempts: u32 = 0;
    loop {
        match job() {
            Ok(()) => return Ok(()),
            Err(err) if !err.is_transient() => return Err(err),
            Err(err) => {
                failed_attempts += 1;
                if failed_attempts >= config.max_attempts {
                    return Err(err);
                }
                let delay_ms = config.retry_delay_ms(failed_attempts - 1);
                sleeper.sleep_ms(delay_ms);
            }
        }
    }
}

//! Integration coverage for the bounded exponential retry policy.

use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

fn config(max_attempts: u32, base_delay_ms: u64, max_delay_ms: u64) -> RetryConfig {
    RetryConfig {
        max_attempts,
        base_delay_ms,
        max_delay_ms,
    }
}

fn transient(msg: &str) -> RetryError {
    RetryError::Transient(msg.to_string())
}

fn permanent(msg: &str) -> RetryError {
    RetryError::Permanent(msg.to_string())
}

#[test]
fn success_on_first_attempt_never_sleeps() {
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;
    let result = run_job(
        &config(3, 10, 100),
        &mut sleeper,
        || {
            calls += 1;
            Ok(())
        },
    );
    assert_eq!(result, Ok(()));
    assert_eq!(calls, 1);
    assert!(sleeper.sleeps.is_empty());
}

#[test]
fn permanent_error_returns_immediately() {
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;
    let result = run_job(
        &config(5, 10, 100),
        &mut sleeper,
        || {
            calls += 1;
            Err(permanent("bad input"))
        },
    );
    assert_eq!(result, Err(permanent("bad input")));
    assert_eq!(calls, 1);
    assert!(sleeper.sleeps.is_empty());
}

#[test]
fn transient_errors_retried_with_exponential_delays_until_success() {
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;
    let result = run_job(
        &config(5, 10, 1000),
        &mut sleeper,
        || {
            calls += 1;
            if calls <= 3 {
                Err(transient("network blip"))
            } else {
                Ok(())
            }
        },
    );
    assert_eq!(result, Ok(()));
    assert_eq!(calls, 4);
    assert_eq!(sleeper.sleeps, vec![10, 20, 40]);
}

#[test]
fn max_attempts_includes_first_call() {
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;
    let result = run_job(
        &config(2, 10, 100),
        &mut sleeper,
        || {
            calls += 1;
            Err(transient("flaky"))
        },
    );
    assert_eq!(result, Err(transient("flaky")));
    assert_eq!(calls, 2);
    assert_eq!(sleeper.sleeps, vec![10]);
}

#[test]
fn single_attempt_never_retries() {
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;
    let result = run_job(
        &config(1, 10, 100),
        &mut sleeper,
        || {
            calls += 1;
            Err(transient("flaky"))
        },
    );
    assert_eq!(result, Err(transient("flaky")));
    assert_eq!(calls, 1);
    assert!(sleeper.sleeps.is_empty());
}

#[test]
fn delays_saturate_at_max_delay_ms() {
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;
    let result = run_job(
        &config(10, 10, 30),
        &mut sleeper,
        || {
            calls += 1;
            Err(transient("always failing"))
        },
    );
    assert_eq!(result, Err(transient("always failing")));
    assert_eq!(calls, 10);
    assert_eq!(sleeper.sleeps, vec![10, 20, 30, 30, 30, 30, 30, 30, 30]);
}

#[test]
fn huge_exponent_saturates_without_overflow() {
    // base_delay = 1 and 100 retries would need 2^100 ms if unbounded,
    // which overflows u64; the policy must saturate at max_delay_ms.
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;
    let result = run_job(
        &config(101, 1, 5_000),
        &mut sleeper,
        || {
            calls += 1;
            Err(transient("still flaky"))
        },
    );
    assert_eq!(result, Err(transient("still flaky")));
    assert_eq!(calls, 101);
    assert_eq!(sleeper.sleeps.len(), 100);
    assert!(sleeper.sleeps.iter().all(|&ms| ms <= 5_000));
    assert_eq!(sleeper.sleeps[0], 1);
    assert_eq!(sleeper.sleeps[12], 4096);
    assert_eq!(sleeper.sleeps[13], 5_000); // 8192 capped to max
    assert_eq!(sleeper.sleeps[99], 5_000);
}

#[test]
fn permanent_error_after_transient_failures_aborts() {
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;
    let result = run_job(
        &config(10, 10, 1000),
        &mut sleeper,
        || {
            calls += 1;
            if calls == 1 {
                Err(transient("flaky"))
            } else {
                Err(permanent("invalid payload"))
            }
        },
    );
    assert_eq!(result, Err(permanent("invalid payload")));
    assert_eq!(calls, 2);
    assert_eq!(sleeper.sleeps, vec![10]);
}
